INSERT INTO `soal` VALUES ('447','7','15','Poster banyak digunakan sebagai media&hellip;','1','Promosi, lomba, iklan','Iklan, lomba, dan pengumuman','Pengumuman, promosi, dan lomba','Pengumuman, promosi, dan iklan','Lomba, iklan dan iformasi','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('448','7','16','<p>Dalam rangka membantu dan mengabdi untuk Kesehatan Masyarakat, para remana membuat poster agar Masyarakat tertarik untuk mendapatkan penyuluhan Kesehatan.</p>\r\n<p>Kalimat poster yang sesuai dengan ilustrasi tersebut adalah&hellip;</p>','1','<p>Memberi bantuan kepada orang lain berarti menyelamatkan orang lain</p>','<p>Mengguanakan obat harus secara teratur dan sesuai hukum</p>','<p>Kemarin sakir, hari ini sehat, besok sehat, lusa sehat.</p>','<p>Ada penyuluhan Kesehatan dan ikut penyuluhan itu dengan baik</p>','<p>Kesehatan terjaga, imunitas akan lebih baik.</p>','A','','','','','','','');
INSERT INTO `soal` VALUES ('449','7','17','Berdasarkan defenisinya, hal apa yang paling penting dari kemunculan sebuah berita&hellip;','1','Fakta dari sebuah peristiwa',' Pendapat dari narasumber','Prediksi dari suatu kejadian','Ketegasan gagasan penulis','Alur peristiwa yang menarik','A',NULL,'','','','','','');
