INSERT INTO `soal` VALUES ('932','6','31','<p>Bacalah penggalan hikayat berikut!</p>\r\n<p>&ldquo;Kita harus rakat mufakat, bantu membantu, bahu membahu. Setuju?&rdquo;</p>\r\n<p>Nilai yang terkandung dalam kalimat penggalan hikayat diatas adalah&hellip;</p>','1','<p>Nilai Pendidikan</p>','<p>Nilai Religius</p>','<p>Nilai Moral</p>','<p>Nilai Sosial</p>','<p>Nilai Persahabatan</p>','A','','','','','','','');
INSERT INTO `soal` VALUES ('933','6','32','<p>Bacalah penggalan hikayat berikut!</p>\r\n<p>Iya memohon pada sang pencipta agar diberi sebuah pulau.&ldquo;Dengan memanjatkan puji dan syukur kepada sang pencipta, Ia menamakannya pulau Halimun.&rdquo;</p>\r\n<p>Nilai yang terkandung dalam kalimat penggalan hikayat diatas adalah&hellip;</p>','1','<p>Nilai Pendidikan</p>','<p>Nilai Religius</p>','<p>Nilai Moral</p>','<p>Nilai Sosial</p>','<p>Nilai Persahabatan</p>','B','','','','','','','');
