INSERT INTO `soal` VALUES ('1798','1','16','Berikut ini adalah contoh cabang iman yang termasuk dalam ranah perbuatan (anggota badan / Amalun bil Arkan), kecuali...','1','Melaksanakan shalat fardhu dan sunnah','Berpuasa di bulan Ramadhan','Mencintai Allah dan Rasul-Nya','Berjihad di jalan Allah','Menjaga kebersihan (thaharah)','C',NULL,'','','','','','');
