INSERT INTO `soal` VALUES ('2085','17','13','Manakah dari perangkat berikut yang tidak termasuk perangkat output..','1','Monitor ','Speaker ','Proyektor ','Flashdisk','Printer','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2086','17','14','Perangkat output yang digunakan untuk menampilkan gambar atau video ke layar lebar adalah... ','1','Printer ','Keyboard ','Monitor ','Speaker ','Proyektor','E',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2087','17','15','Pilih pernyataan yang benar mengenai sistem operasi...','1','Sistem operasi adalah perangkat keras komputer. ','Sistem operasi tidak diperlukan dalam pengoperasian komputer. ','Sistem operasi mengelola sumber daya komputer dan menyediakan antarmuka bagi pengguna. ','Sistem operasi hanya dapat diinstal sekali seumur hidup komputer. ','Sistem operasi hanya berfungsi sebagai perangkat lunak pengolah teks.','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2088','17','16','Manakah langkah pertama dalam proses instalasi sistem operasi,..?','1','Mengkonfigurasi pengaturan jaringan. ','Memasang perangkat keras tambahan. ','Memformat hard drive. ','Memasukkan media instalasi (contoh: CD, USB) ke dalam komputer. ','Mendaftarkan produk lisensi.','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2089','17','17','Apa tujuan dari proses partisi saat menginstal sistem operasi...?','1','Menghapus semua data yang ada di hard drive. ','Memeriksa integritas media instalasi. ','Membagi hard drive menjadi beberapa bagian logis untuk menyimpan data dan sistem operasi. ','Menginstal perangkat lunak ke hard drive. ','Memeriksa kesalahan sistem operasi yang ada.','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2090','17','18','Apa yang dimaksud dengan &quot;lisensi perangkat lunak&quot; dalam konteks instalasi sistem operasi...?','1','Sebuah perangkat keras yang diperlukan untuk menginstal sistem operasi. ','Izin resmi untuk menggunakan perangkat lunak tertentu dengan syarat-syarat tertentu. ','Sebuah alat untuk mempercepat proses instalasi sistem operasi. ','Sebuah perangkat lunak yang harus diinstal bersama dengan sistem operasi. ','Sebuah kunci untuk mengunci sistem operasi agar tidak dapat diakses oleh pengguna lain.','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2091','17','19','Apa yang dimaksud dengan &quot;format&quot; saat menginstal sistem operasi..?','1','Proses mengubah tampilan antarmuka sistem operasi. ','Proses mengatur waktu dan tanggal di komputer. ','Proses menghapus semua data dari hard drive dan memformatnya untuk digunakan oleh sistem operasi. ','Proses mengganti perangkat keras di komputer. ','Proses menginstal driver perangkat keras.','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2092','17','20','Manakah dari pernyataan berikut yang benar mengenai partisi hard drive saat menginstal sistem operasi..','1','Partisi hard drive hanya diperlukan jika Anda ingin menghapus semua data dari komputer. ','Partisi hard drive digunakan untuk membagi hard drive menjadi beberapa bagian fisik. ','Partisi hard drive digunakan untuk menginstal sistem operasi, tetapi tidak mempengaruhi penyimpanan data. ','Partisi hard drive hanya dapat dilakukan oleh teknisi komputer berlisensi. ','Partisi hard drive tidak memiliki peran dalam proses instalasi sistem operasi.','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2093','17','21','Apa yang dimaksud dengan &quot;pengguna akhir&quot; dalam konteks instalasi sistem operasi..?','1','Orang yang menginstal sistem operasi. ','Orang yang merancang sistem operasi. ','Orang yang menggunakan komputer dan berinteraksi dengan sistem operasi. ','Sebuah jenis perangkat keras komputer. ','Orang yang bertanggung jawab untuk memperbaiki sistem operasi yang rusak.','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2094','17','22','Apa yang dimaksud dengan &quot;instalasi aplikasi&quot; dalam konteks perangkat lunak komputer..?','1','Proses menghapus aplikasi yang sudah terinstal. ','Proses membuat salinan cadangan aplikasi. ','Proses mengganti sistem operasi. ','Proses mengatur ulang pengaturan aplikasi. ','Proses memasang perangkat lunak pada komputer atau perangkat lainnya.','E',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2095','17','23','Apa yang harus Anda perhatikan sebelum menginstal aplikasi pada komputer Anda...?','1','Jumlah aplikasi yang sudah terinstal pada komputer. ','Spesifikasi minimum perangkat keras yang diperlukan oleh aplikasi. ','Warna latar belakang desktop komputer. ','Banyaknya file yang ada di Recycle Bin. ','Ukuran tampilan layar komputer.','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2096','17','24','Apa peran komite K3LH di tempat kerja,..?','1','Menetapkan aturan ketat tanpa pertimbangan ','Mengawasi pelanggaran dan memberikan hukuman ','Mengevaluasi dan memberikan saran untuk perbaikan K3LH ','Menyembunyikan informasi keselamatan ','Membuat kebijakan tanpa memperhatikan kebutuhan karyawan','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2097','17','25','Mengapa penggunaan gelang anti-statis direkomendasikan saat merakit PC,..?','1','Mencegah komponen dari getaran','Mempercepat proses booting','Mencegah kerusakan perangkat akibat listrik statis','Meningkatkan kinerja RAM','Menyimpan data','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2098','17','26','Apa kegunaan kipas pada PC?','1','Menjaga agar casing tetap dingin','Menyaring sinyal listrik','Menyimpan data','Mengontrol koneksi jaringan','Memproses grafis','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2099','17','27','Apa yang perlu Anda lakukan jika instalasi aplikasi mengalami kegagalan atau terhenti secara tiba-tiba..','1','Membuang komputer yang digunakan. ','Menutup semua program yang sedang berjalan. ','Mengganti sistem operasi komputer. ','Memeriksa pesan kesalahan yang muncul dan mengikuti petunjuk untuk memperbaikinya. ','Menghubungi produsen perangkat keras komputer.','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2100','17','28','Apa yang perlu Anda lakukan setelah berhasil menginstal aplikasi baru di perangkat seluler Anda?','1','Mematikan perangkat seluler. ','Menghapus semua aplikasi yang sudah terinstal sebelumnya. ','Memeriksa dan mengatur pengaturan aplikasi sesuai kebutuhan. ','Tidak perlu melakukan apa-apa, aplikasi akan berjalan dengan baik secara otomatis. ','Mengganti nomor telepon pada perangkat seluler.','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2101','17','29','Apa yang dimaksud dengan budaya...','1','Sebuah negara ','Sebuah agama ','Seperangkat aturan hukum ','Cara hidup bersama, termasuk nilai, kepercayaan, adat istiadat, makanan, dan seni ','Kumpulan bangunan bersejarah','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2102','17','30','Apa fungsi dari motherboard dalam sebuah PC,..?','1','Menyimpan data','Menjalankan perangkat lunak','Mengontrol arus listrik','Menyediakan koneksi antar komponen','Menyaring sinyal grafis','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2103','17','31','Bagaimana budaya dapat berubah seiring waktu..','1','Budaya selalu tetap sama dan tidak berubah ','Melalui adaptasi, inovasi, migrasi, dan interaksi sosial ','Hanya melalui pengaruh negatif ','Hanya melalui pengaruh politik ','Hanya melalui perubahan generasi','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2104','17','32','Apa yang dimaksud dengan mutu dalam konteks manajemen...','1','Jumlah produksi ','Tingkat keuntungan ','Kualitas atau karakteristik produk atau layanan ','Harga produk ','Waktu produksi','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2105','17','33','Komponen mana yang bertanggung jawab untuk menyimpan data permanen pada PC?','1','CPU','GPU','RAM','Hardisk','Flaskdisk','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2106','17','34','Salah satu tujuan utama manajemen mutu adalah,..','1','Menghasilkan produk dengan biaya rendah ','Meningkatkan biaya produksi ','Menekan inovasi ','Memastikan kepuasan pelanggan ','Menyediakan produk dengan biaya tinggi','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2107','17','35','Komponen pelindung luar pada kabel fiber optic adalah&hellip;','1','Core','Cladding','Jacket','Coating','Connector','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2108','17','36','Bagaimana peran inspeksi dalam manajemen mutu','1','Inspeksi adalah satu-satunya metode untuk mengukur mutu produk ','Inspeksi dilakukan setelah produk selesai diproduksi ','Inspeksi tidak relevan dalam manajemen mutu ','Inspeksi adalah metode pencegahan untuk mengidentifikasi masalah sejak awal ','Inspeksi hanya berfokus pada biaya produksi','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2109','17','37','Bagian inti kabel fiber optic yang berfungsi sebagai jalur utama rambatan cahaya adalah&hellip;','1','Cladding','Jacket','Core','Buffer coating','Strength member','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2110','17','38','Jenis fiber optic yang digunakan untuk komunikasi jarak jauh karena memiliki redaman rendah adalah&hellip;','1','Multi Mode Step Index','Multi Mode Graded Index','Single Mode','Plastic Optical Fiber','Duplex fiber','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2111','17','39','Alat yang digunakan untuk menyambungkan dua serat optik secara permanen disebut&hellip;','1','Punch down tool','OTDR','Splicer','Crimping tool','Optical Transmitter','C',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('2112','17','40','Keunggulan fiber optic dibanding kabel tembaga adalah, kecuali&hellip;','1','Bebas interferensi elektromagnetik','Kapasitas bandwidth besar','Dapat mengirim data jarak jauh','Harga instalasi sangat murah','Keamanan data lebih baik','D',NULL,'','','','','','');
